import React from "react";
import { Text, View } from "react-native";
import { useSkeuo } from "../theme";
import { SkeuoGlyph } from "../icons";
export type Transaction = {
  id: string;
  name: string;
  category: string;
  amount: string;
  income?: boolean;
};
export const sampleTransactions: Transaction[] = [
  { id: "1", name: "Corner coffee", category: "Food · Today", amount: "−₹180" },
  {
    id: "2",
    name: "Monthly salary",
    category: "Bank · Today",
    amount: "+₹48,000",
    income: true,
  },
  {
    id: "3",
    name: "Sunday groceries",
    category: "Shopping · Yesterday",
    amount: "−₹1,240",
  },
  {
    id: "4",
    name: "Metro pass",
    category: "Transport · Yesterday",
    amount: "−₹450",
  },
];
export function TransactionList({
  items = sampleTransactions,
}: {
  items?: Transaction[];
}) {
  const { colors: c } = useSkeuo();
  return (
    <View>
      {items.length === 0 ? (
        <Text style={{ color: c.muted, paddingVertical: 24 }}>
          No transactions match your search.
        </Text>
      ) : (
        items.map((item, i) => (
          <View
            key={item.id}
            style={{
              flexDirection: "row",
              gap: 12,
              paddingVertical: 15,
              borderTopWidth: i ? 1 : 0,
              borderColor: c.edge,
              alignItems: "center",
            }}
          >
            <View
              style={{
                width: 42,
                height: 42,
                borderRadius: 12,
                borderWidth: 1,
                borderColor: c.edge,
                backgroundColor: c.well,
                alignItems: "center",
                justifyContent: "center",
              }}
            >
              <SkeuoGlyph
                name={item.income ? "arrow" : "transactions"}
                color={c.muted}
              />
            </View>
            <View style={{ flex: 1, gap: 4 }}>
              <Text style={{ color: c.ink, fontSize: 14, fontWeight: "600" }}>
                {item.name}
              </Text>
              <Text style={{ color: c.muted, fontSize: 11 }}>
                {item.category}
              </Text>
            </View>
            <Text
              style={{
                color: item.income ? c.accent : c.ink,
                fontSize: 14,
                fontWeight: "600",
              }}
            >
              {item.amount}
            </Text>
          </View>
        ))
      )}
    </View>
  );
}

import React, { createContext, useContext } from "react";
import { useColorScheme } from "nativewind";
import * as Haptics from "expo-haptics";

export const themes = {
  light: {
    background: "#ffffff",
    surface: "#f5f5f2",
    raised: "#fafaf8",
    well: "#e9e9e5",
    edge: "#d1d1cb",
    base: "#d9d9d3",
    ink: "#202020",
    muted: "#686863",
    accent: "#365e50",
    accentInk: "#ffffff",
  },
  dark: {
    background: "#000000",
    surface: "#191919",
    raised: "#252525",
    well: "#111111",
    edge: "#3b3b39",
    base: "#080808",
    ink: "#efefeb",
    muted: "#aaaAA5",
    accent: "#9ab5a6",
    accentInk: "#14251c",
  },
};
type ThemeState = { colors: typeof themes.light; dark: boolean; haptics: boolean; onSound?: () => void };
const Context = createContext<ThemeState | null>(null);
export function SkeuoProvider({
  children,
  appearance = "system",
  haptics = false,
  onSound,
  colors: overrides,
}: {
  children: React.ReactNode;
  appearance?: "light" | "dark" | "system";
  haptics?: boolean;
  onSound?: () => void;
  colors?: Partial<typeof themes.light>;
}) {
  const { colorScheme: system } = useColorScheme();
  const dark = (appearance === "system" ? system : appearance) === "dark";
  return (
    <Context.Provider
      value={{
        colors: { ...(dark ? themes.dark : themes.light), ...overrides },
        dark,
        haptics,
        onSound,
      }}
    >
      {children}
    </Context.Provider>
  );
}
export function useSkeuo(): ThemeState {
  const context = useContext(Context);
  const { colorScheme } = useColorScheme();
  return context ?? { colors: colorScheme === "dark" ? themes.dark : themes.light, dark: colorScheme === "dark", haptics: false };
}
export function useFeedback() {
  const { haptics, onSound } = useSkeuo();
  return () => {
    onSound?.();
    if (haptics) void Haptics.selectionAsync().catch(() => {});
  };
}

import { Text } from "react-native";
/** Simple line symbols keep the portable controls independent of an icon package. Hosts may pass their own icons. */
export function SkeuoGlyph({
  name,
  color = "#686863",
  size = 21,
}: {
  name: string;
  color?: string;
  size?: number;
}) {
  const symbols: Record<string, string> = {
    home: "⌂",
    transactions: "⇄",
    analysis: "▥",
    profile: "○",
    focus: "◷",
    habits: "✓",
    journal: "≡",
    settings: "⚙",
    activity: "↗",
    goals: "◎",
    saved: "▱",
    add: "+",
    arrow: "↗",
    back: "‹",
    next: "›",
    play: "▶",
    pause: "Ⅱ",
    sound: "♪",
  };
  return (
    <Text
      accessible={false}
      style={{
        color,
        fontSize: size,
        lineHeight: size + 4,
        textAlign: "center",
      }}
    >
      {symbols[name] ?? "◇"}
    </Text>
  );
}
